mapper.insert:
        INSERT INTO RSID_VHCL (
              RSID_VHCL_NO
            , VHCL_NM
            , VHCL_NO
            , USER_NO
            , HO_NO
            , VHCL_STTS_CD
            , REG_DT
            , VHCL_FILE_NO
        )VALUES (
              SEQ_RSID_VHCL.NEXTVAL
            , #{vhclNm}
            , #{vhclNo}
            , #{userNo}
            , #{hoNo}
            , #{vhclSttsCd}
            , SYSDATE
            , #{vhclFileNo}
        )

mapper.select:
SELECT COUNT(*)
FROM RSID_VHCL
WHERE VHCL_NO = #{vhclNo}

SELECT COUNT(*)
FROM rsid_vhcl
WHERE user_no = #{userNo}
